using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using System.Windows;
using System.Windows.Controls;
internal static class CompleteWorkspaceAcceptance {
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
 internal static void Test(string folder){
  var today=new DateTime(2028,1,20);var draft=NaturalReminders.Parse("Payer le loyer le 5 de chaque mois",today);Check(draft.Title=="Payer le loyer"&&draft.Due=="2028-02-05"&&draft.Anchor==5&&draft.Repeat=="monthly","Rappel mensuel");draft=NaturalReminders.Parse("Appeler demain à 14h30",today);Check(draft.Title=="Appeler"&&draft.Due=="2028-01-21"&&draft.Time=="14:30","Demain et heure");draft=NaturalReminders.Parse("Sport chaque lundi à 18h",today);Check(draft.Due=="2028-01-24"&&draft.Repeat=="weekly"&&draft.Time=="18:00","Jour de semaine");draft=NaturalReminders.Parse("Préparer le bilan le 31 de chaque mois",new DateTime(2028,2,10));Check(draft.Due=="2028-02-29"&&draft.Anchor==31,"Ancrage mensuel");foreach(var text in new[]{"Sans date","Appeler demain à 25h","Payer le 32 de chaque mois","Réunion le 31/02/2028"}){bool bad=false;try{NaturalReminders.Parse(text,today);}catch(InvalidDataException){bad=true;}Check(bad,"Phrase invalide acceptée : "+text);}
  Check(WeeklyPlanning.MinutesOnDay(new DateTime(2028,1,20,23,0,0),new DateTime(2028,1,21,1,0,0),new DateTime(2028,1,21))==60,"Rendez-vous à cheval sur minuit");var store=new Store(Path.Combine(folder,"complete-workspace"));var task=NaturalReminders.Add(store,NaturalReminders.Parse("Appeler demain à 14h30",today),"Personnel");string due=task.due;var block=new TimeBlock{id="block",taskId=task.id,date="2028-01-21",time="10:00",minutes=60};WeeklyPlanning.Save(store,block);store.Value.events.Add(new CalendarEvent{id="overlap",title="RDV",date=block.date,time="10:30",duration=60});store.Save();Check(WeeklyPlanning.Conflicts(store.Value,block).Count==1&&WeeklyPlanning.Load(store.Value,Schedule.Day(block.date))==120,"Chevauchement et charge");Check(new Store(store.Root).Value.timeBlocks.Single().time=="10:00"&&task.due==due&&task.status=="todo","Planning indépendant de l’échéance");var moved=WeeklyPlanning.Dropped(store.Value,"block/block",new DateTime(2028,1,22),795);Check(moved.id==block.id&&moved.date=="2028-01-22"&&moved.time=="13:15"&&moved.minutes==60,"Déplacement de créneau");bool invalid=false;try{WeeklyPlanning.Save(store,new TimeBlock{id="invalid",taskId=task.id,date=block.date,time="23:45",minutes=60});}catch(InvalidDataException){invalid=true;}Check(invalid&&store.Value.timeBlocks.Count==1,"Créneau invalide et annulation");
  var note=new NotePage{id="history",title="Note",body="Version une"};store.Value.pages.Add(note);store.Save();note.body="Version deux";store.Save();var loaded=new Store(store.Root);Check(loaded.Value.noteHistory.Single().body=="Version une","Historique automatique");NoteHistory.Restore(loaded,loaded.Value.noteHistory.Single().id);Check(loaded.Value.pages.Single().body=="Version une"&&loaded.Value.noteHistory.Any(r=>r.body=="Version deux"),"Restauration avec retour");for(int i=0;i<20;i++){loaded.Value.pages.Single().body="Version "+i;loaded.Save();}Check(loaded.Value.noteHistory.Count==15,"Limite historique");var state=Path.Combine(loaded.Root,"state.json");File.Delete(state);Directory.CreateDirectory(state);int historyCount=loaded.Value.noteHistory.Count;loaded.Value.pages.Single().body="Échec";invalid=false;try{loaded.Save();}catch(IOException){invalid=true;}catch(UnauthorizedAccessException){invalid=true;}Directory.Delete(state);Check(invalid&&loaded.Value.noteHistory.Count==historyCount,"Historique après échec de sauvegarde");loaded.Save();
  string spaceRoot=Path.Combine(folder,"spaces-test");var personal=new Store(WorkspaceSpaces.DataRoot(spaceRoot,"perso"));personal.Value.pages.Add(new NotePage{id="perso",title="Perso",body="Privé"});personal.Save();WorkspaceSpaces.Activate(spaceRoot,"travail");var work=new Store(WorkspaceSpaces.ActiveRoot(spaceRoot));Check(work.Value.pages.Count==0&&work.Value.tasks.Count==0,"Isolation des espaces");work.Value.settings.DisplayName="Travail";work.Save();WorkspaceSpaces.Activate(spaceRoot,"perso");Check(new Store(WorkspaceSpaces.ActiveRoot(spaceRoot)).Value.pages.Single().body=="Privé","Espace actuel conservé");invalid=false;try{WorkspaceSpaces.DataRoot(spaceRoot,"../escape");}catch(InvalidDataException){invalid=true;}Check(invalid,"Chemin d’espace invalide accepté");
  string backups=Path.Combine(folder,"auto-backups");var json=new JavaScriptSerializer{MaxJsonLength=8*1024*1024};var options=loaded.Value.settings.AutoBackup;options.enabled=true;options.folder=backups;Check(AutomaticBackups.Due(options,DateTime.UtcNow),"Première sauvegarde");options.lastAttempt=DateTime.UtcNow.Ticks;Check(!AutomaticBackups.Due(options,DateTime.UtcNow),"Délai de reprise");string latest="";Directory.CreateDirectory(backups);File.WriteAllText(Path.Combine(backups,"mes-notes.txt"),"Ne pas supprimer");for(int i=0;i<3;i++)latest=AutomaticBackups.Create(loaded,json.Serialize(loaded.Value),backups,options.id,2);Check(Directory.GetFiles(backups,"*.mespace").Length==2&&File.Exists(Path.Combine(backups,"mes-notes.txt")),"Rotation de sauvegardes");var restore=new Store(Path.Combine(folder,"auto-restore"));using(var plan=FullBackup.Prepare(restore,latest))FullBackup.Commit(restore,plan);Check(restore.Value.noteHistory.Count==15&&restore.Value.timeBlocks.Count==1,"Restauration historique et planning");invalid=false;try{AutomaticBackups.CheckFolder(loaded,Path.Combine(loaded.Root,"backup"));}catch(InvalidDataException){invalid=true;}Check(invalid,"Sauvegarde dans les données acceptée");File.WriteAllText(Path.Combine(folder,"COMPLETE_WORKSPACE_PASS.txt"),"PASS: natural dates/recurrences and invalid input; planning overlap/load/persistence/rollback; note history capture/restore/limits/failure; isolated spaces and safe paths; automatic backup cooldown/rotation/restore, unrelated files preserved.");
 }
}
internal sealed partial class ModernWorkspace {
 void VerifyCompleteWorkspace(string folder){
  var t=new WorkTask{id="week-ui",title="Préparer le dossier",project="Personnel",priority="Haute",status="todo",due=DateTime.Today.ToString("yyyy-MM-dd")};store.Value.tasks.Add(t);store.Save();bool captured=false;dialogProbe=delegate(Window w){var boxes=LogicalControls<TextBox>(w).ToList();boxes[0].Text="Appeler demain à 14h30";ClickWizard(w,"Créer le rappel");captured=true;return true;};try{NaturalReminderDialog();}finally{dialogProbe=null;}if(!captured||!store.Value.tasks.Any(x=>x.title=="Appeler"&&x.dueTime=="14:30"))throw new Exception("Rappel naturel UI");
  dialogProbe=delegate(Window w){var combo=LogicalControls<ComboBox>(w).First();combo.SelectedItem=t;ClickWizard(w,"Enregistrer");return true;};try{EditTimeBlock(null,DateTime.Today,"09:00");}finally{dialogProbe=null;}if(!new Store(store.Root).Value.timeBlocks.Any(b=>b.taskId==t.id&&b.time=="09:00"))throw new Exception("Créneau UI");var existingBlock=store.Value.timeBlocks.First(b=>b.taskId==t.id);var movedBlock=WeeklyPlanning.Dropped(store.Value,"block/"+existingBlock.id,DateTime.Today.AddDays(1),795);dialogProbe=delegate(Window w){ClickWizard(w,"Enregistrer");return true;};try{EditTimeBlock(movedBlock,DateTime.Today.AddDays(1),movedBlock.time);}finally{dialogProbe=null;}if(store.Value.timeBlocks.First(b=>b.id==existingBlock.id).time!="13:15")throw new Exception("Déplacement créneau UI");Go("Planning semaine");PreviewSized(Path.Combine(folder,"Planning-semaine.png"),1280,900);
  var note=new NotePage{id="history-ui",title="Note à restaurer",body="Ancien texte"};store.Value.pages.Add(note);store.Save();note.body="Texte actuel";store.Save();var revision=store.Value.noteHistory.First(r=>r.noteId==note.id);dialogProbe=delegate(Window w){if(!LogicalControls<TextBox>(w).Any(b=>b.IsReadOnly&&b.Text=="Ancien texte"))throw new Exception("Aperçu historique");ClickWizard(w,"Restaurer cette version");return true;};try{OpenNoteRevision(revision);}finally{dialogProbe=null;}if(store.Value.pages.First(n=>n.id==note.id).body!="Ancien texte")throw new Exception("Restauration note UI");foreach(var page in new[]{"Historique des notes","Mes espaces","Sauvegardes automatiques"}){Go(page);PreviewSized(Path.Combine(folder,page.Replace(" ","-")+".png"),1200,800);}store.Value.settings.PrivacyMode=true;Refresh();if(spacesButton.Visibility!=Visibility.Collapsed)throw new Exception("Espaces visibles en mode discret");store.Value.settings.PrivacyMode=false;Refresh();File.WriteAllText(Path.Combine(folder,"COMPLETE_WORKSPACE_UI_PASS.txt"),"PASS: natural reminder real dialog, task scheduling via real dialog, rendered week/history/spaces/backup settings, note restore action, privacy. Physical drag and space relaunch require target PC verification.");
 }
}
